FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 100: std's API builtins no feature calls. Generated by tools/fixtures/gen-batch-100.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v is Vector) returns array
{
    return [roundToPrecision(v[0], 6), roundToPrecision(v[1], 6), roundToPrecision(v[2], 6)];
}

function roundAll(a is array) returns array
{
    return mapArray(a, function(x) { return x is number ? roundToPrecision(x, 6) : (x is array ? roundAll(x) : x); });
}

// flip: a block's top extracted as a sheet, its orientation flipped: its normal before and after
export function c001(context is Context, id is Id)
{
    fCuboid(context, id + "base", { "corner1" : vector(0, 0, 0) * millimeter, "corner2" : vector(10, 20, 30) * millimeter });
    opExtractSurface(context, id + "sheet", { "faces" : qContainsPoint(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), vector(5, 10, 30) * millimeter) });
    const before = round6(evFaceTangentPlane(context, { "face" : qOwnedByBody(qCreatedBy(id + "sheet", EntityType.BODY), EntityType.FACE), "parameter" : vector(0.5, 0.5) }).normal);
    opFlipOrientation(context, id + "flip", { "bodies" : qCreatedBy(id + "sheet", EntityType.BODY) });
    return { "before" : before, "after" : round6(evFaceTangentPlane(context, { "face" : qOwnedByBody(qCreatedBy(id + "sheet", EntityType.BODY), EntityType.FACE), "parameter" : vector(0.5, 0.5) }).normal) };
}

// bspline: a sheet from a B-spline surface, degree 2 by 1, its middle row raised 10 mm
export function c002(context is Context, id is Id)
{
    const surface = bSplineSurface({ "uDegree" : 2, "vDegree" : 1, "isUPeriodic" : false, "isVPeriodic" : false,
        "controlPoints" : controlPointMatrix([[vector(0, 0, 0) * millimeter, vector(0, 20, 0) * millimeter], [vector(15, 0, 10) * millimeter, vector(15, 20, 10) * millimeter], [vector(30, 0, 0) * millimeter, vector(30, 20, 0) * millimeter]]),
        "uKnots" : knotArray([0, 0, 0, 1, 1, 1]), "vKnots" : knotArray([0, 0, 1, 1]) });
    opCreateBSplineSurface(context, id + "surface1", { "bSplineSurface" : surface });
    return { "normal" : round6(evFaceTangentPlane(context, { "face" : qOwnedByBody(qCreatedBy(id + "surface1", EntityType.BODY), EntityType.FACE), "parameter" : vector(0.5, 0.5) }).normal) };
}

// evaluate: a quadratic spline evaluated at four parameters, with two derivatives
export function c003(context is Context, id is Id)
{
    const spline = bSplineCurve({ "degree" : 2, "isPeriodic" : false, "controlPoints" : [vector(0, 0, 0) * millimeter, vector(10, 10, 0) * millimeter, vector(20, 0, 5) * millimeter], "knots" : knotArray([0, 0, 0, 1, 1, 1]) });
    const values = evaluateSpline({ "spline" : spline, "parameters" : [0, 0.25, 0.5, 1], "nDerivatives" : 2 });
    return { "values" : mapArray(values, function(row) { return mapArray(row, function(p) { return round6(p / millimeter); }); }) };
}

// json: a JSON string parsed
export function c004(context is Context, id is Id)
{
    return { "parsed" : parseJson("{\"a\" : 1, \"b\" : [1, 2.5, \"x\"], \"c\" : null, \"d\" : true, \"e\" : { \"f\" : \"g\" } }") };
}

// mass: a block's approximate mass properties (1 kg/m³), and its faces' (1 kg/m²)
export function c005(context is Context, id is Id)
{
    fCuboid(context, id + "base", { "corner1" : vector(0, 0, 0) * millimeter, "corner2" : vector(10, 20, 30) * millimeter });
    const solid = evApproximateMassProperties(context, { "entities" : qCreatedBy(id + "base", EntityType.BODY), "density" : 1 * kilogram / meter ^ 3 });
    const faces = evApproximateMassProperties(context, { "entities" : qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), "density" : 1 * kilogram / meter ^ 2 });
    return { "mass" : roundToPrecision(solid.mass / kilogram * 1e9, 3), "centroid" : round6(solid.centroid / millimeter), "volume" : roundToPrecision(solid.volume / millimeter ^ 3, 3), "faceMass" : roundToPrecision(faces.mass / kilogram * 1e6, 3), "faceCentroid" : round6(faces.centroid / millimeter) };
}

// deviation: points' deviations from a block (one inside, one out past a face, one off a corner)
export function c006(context is Context, id is Id)
{
    fCuboid(context, id + "base", { "corner1" : vector(0, 0, 0) * millimeter, "corner2" : vector(10, 20, 30) * millimeter });
    const deviations = evPointsDeviation(context, { "points" : [vector(5, 5, 5) * millimeter, vector(5, 10, 40) * millimeter, vector(13, 24, 30) * millimeter], "topologies" : qCreatedBy(id + "base", EntityType.BODY), "allDeviations" : true });
    return { "deviations" : mapArray(deviations, function(d) { return { "deviation" : roundToPrecision(d.deviation / millimeter, 6), "topologyPoint" : round6(d.topologyPoint / millimeter) }; }) };
}

// tolerance: a block's tolerances, its greatest tolerance and its faults
export function c007(context is Context, id is Id)
{
    fCuboid(context, id + "base", { "corner1" : vector(0, 0, 0) * millimeter, "corner2" : vector(10, 20, 30) * millimeter });
    const tolerances = evTolerances(context, { "entities" : qCreatedBy(id + "base", EntityType.BODY) });
    return { "count" : size(tolerances), "max" : evMaxTolerance(context, { "entities" : qCreatedBy(id + "base", EntityType.BODY) }), "faults" : size(evFaults(context, { "entities" : qCreatedBy(id + "base", EntityType.BODY) })) };
}

// curvature: a cylinder's (radius 10) curvature derivative along its circle and along its axis
export function c008(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    const side = qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.CYLINDER);
    const around = evFaceCurvatureDerivative(context, { "face" : side, "parameter" : vector(0.25, 0.5), "direction" : vector(0, 1, 0) });
    const along = evFaceCurvatureDerivative(context, { "face" : side, "parameter" : vector(0.25, 0.5), "direction" : vector(0, 0, 1) });
    return { "around" : roundAll([around[0] * millimeter ^ 2, around[1] * millimeter ^ 2, around[2] * millimeter ^ 2]), "along" : roundAll([along[0] * millimeter ^ 2, along[1] * millimeter ^ 2, along[2] * millimeter ^ 2]) };
}

// approximate: a cylinder's side approximated as a B-spline surface
export function c009(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    const result = evApproximateBSplineSurface(context, { "face" : qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.CYLINDER) });
    return { "degrees" : [result.bSplineSurface.uDegree, result.bSplineSurface.vDegree], "rational" : result.bSplineSurface.isRational, "periodic" : [result.bSplineSurface.isUPeriodic, result.bSplineSurface.isVPeriodic], "uKnots" : roundAll(result.bSplineSurface.uKnots), "vKnots" : roundAll(result.bSplineSurface.vKnots), "rows" : size(result.bSplineSurface.controlPoints), "columns" : size(result.bSplineSurface.controlPoints[0]), "boundaries" : size(result.boundaryBSplineCurves) };
}

// debug: debug display calls: auxiliary entities, a reference frame, a timer
export function c010(context is Context, id is Id)
{
    fCuboid(context, id + "base", { "corner1" : vector(0, 0, 0) * millimeter, "corner2" : vector(10, 20, 30) * millimeter });
    addAuxiliaryEntities(context, id + "aux", qCreatedBy(id + "base", EntityType.BODY), DebugColor.RED);
    addReferenceCSysFrame(context, id + "frame", vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 0, 1));
    startTimer("fixtureTimer");
    printTimer("fixtureTimer");
    return { "done" : true };
}
